let state;try{state=JSON.parse(localStorage.getItem(STORE));if(!state||state.version!==1||!Array.isArray(state.dishes))state=seed()}catch{state=seed()}
let view='menu',category='全部',favOnly=false,query='',sort='recent',bookCategory='全部',bookCover=false,bookBusy=false,month=9,year=2026,selectedDate=TODAY,detailId=null,formMode='dish',formDraft={},toastTimer,randomLast=null;
let favoriteFilters={category:'全部',query:'',sort:'recent'};
function save(){try{localStorage.setItem(STORE,JSON.stringify(state));updateCounts();return true}catch(e){toast('本地保存空间不足，请减少照片或导出备份。');return false}}
function commit(next){const old=state;state=next;if(!save()){state=old;updateCounts();return false}return true}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3400)}
function updateCounts(){document.getElementById('navCount').textContent=state.dishes.length;document.getElementById('favCount').textContent=state.dishes.filter(d=>d.favorite).length}
// A state snapshot owns one small index; photo bytes never enter this cache.
let derivedIndex=null;
function dataIndex(){
 if(derivedIndex?.state===state&&derivedIndex.dishes===state.dishes&&derivedIndex.records===state.records&&derivedIndex.meals===state.meals&&derivedIndex.size===state.dishes.length+state.records.length+state.meals.length)return derivedIndex;
 const byDish=new Map(),recordsByDate=new Map(),mealsByDate=new Map();
 const add=(map,key,item)=>{if(!map.has(key))map.set(key,[]);map.get(key).push(item);};
 for(const record of state.records){add(byDish,record.dishId,record);add(recordsByDate,record.date,record);}
 for(const records of byDish.values())records.sort((a,b)=>b.date.localeCompare(a.date));
 for(const meal of state.meals)add(mealsByDate,meal.date,meal);
 return derivedIndex={state,dishes:state.dishes,records:state.records,meals:state.meals,size:state.dishes.length+state.records.length+state.meals.length,byDish,recordsByDate,mealsByDate,dishesById:new Map(state.dishes.map(d=>[d.id,d])),mealsById:new Map(state.meals.map(m=>[m.id,m]))};
}
function allRecords(id){return dataIndex().byDish.get(id)||[]}
function recordsOn(date){return dataIndex().recordsByDate.get(date)||[]}
function mealsOn(date){return dataIndex().mealsByDate.get(date)||[]}
function lastDate(d){return allRecords(d.id)[0]?.date||d.created}
function dateShort(date){const a=date.split('-');return a[1]+'.'+a[2]}
function dateLong(date){const a=date.split('-');return `${a[0]} 年 ${+a[1]} 月 ${+a[2]} 日`}
function mealBy(id){return dataIndex().mealsById.get(id)}
function dishBy(id){return dataIndex().dishesById.get(id)}
function recordOrigin(d){const r=allRecords(d.id)[0],m=mealBy(r?.mealId);return m?.maker==='自己'?'在家做':m?.place||d.tags[0]||'美味收藏'}
function filtered(){let arr=state.dishes.filter(d=>(category==='全部'||(d.category||'未分类')===category)&&(view!=='favorites'||d.favorite)&&(!query||(d.name+' '+d.tags.join(' ')+' '+d.description).toLowerCase().includes(query.toLowerCase())));return arr.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'zh-CN'):sort==='created'?b.created.localeCompare(a.created):lastDate(b).localeCompare(lastDate(a)))}
function setView(v){
 if(view==='favorites'&&v!=='favorites')favoriteFilters={category,query,sort};
 if(v==='menu'){category='全部';query='';sort='recent'}
 else if(v==='favorites'&&view!=='favorites'){
  category=favoriteFilters.category==='全部'||favoriteFilters.category==='未分类'||state.categories.includes(favoriteFilters.category)?favoriteFilters.category:'全部';
  query=favoriteFilters.query;sort=favoriteFilters.sort;
 }else if(v!=='favorites'){category='全部';query='';sort='recent'}
 view=v;favOnly=v==='favorites';
 document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);b.setAttribute('aria-current',b.dataset.view===v?'page':'false')});
 document.getElementById('breadcrumb').textContent={menu:'我的菜单',favorites:'特别喜欢',book:'翻阅菜单',calendar:'饮食日历',settings:'设置与备份'}[v];
 const search=document.getElementById('globalSearch');search.value=query;search.placeholder=v==='favorites'?'在特别喜欢中查找…':'寻找记忆里的味道…';search.setAttribute('aria-label',v==='favorites'?'搜索特别喜欢的菜名或标签':'搜索菜名或标签');
 render();window.scrollTo({top:0,behavior:'instant'});
}
function pageHead(title,en,sub,meta=''){return `<div class="page-head"><div><div class="eyebrow">${en}</div><h1>${title}</h1><p>${sub}</p></div><div class="head-meta">${meta}</div></div>`}
function foot(){return '<footer class="page-foot">每一道喜欢的菜，都是生活给你的回甘。<span>·</span>笑食天下 · 示例内容 / 交互原型</footer>'}
function render(){updateCounts();document.getElementById('main').innerHTML=({menu:renderMenu,favorites:renderFavorites,book:renderBook,calendar:renderCalendar,settings:renderSettings}[view])();document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}
function renderCollection(dishes,title){return `<section><div class="section-row"><h2 class="section-title">${title}<small id="resultCount">共 ${dishes.length} 道</small></h2><div class="section-controls"><button data-action="random">${icon('shuffle')} 帮我挑一道</button><select id="sortSelect" aria-label="菜品排序"><option value="recent" ${sort==='recent'?'selected':''}>最近吃过</option><option value="created" ${sort==='created'?'selected':''}>最近收录</option><option value="name" ${sort==='name'?'selected':''}>菜名排序</option></select></div></div><div class="filters" id="filters">${renderFilters()}</div><div class="grid" id="foodGrid">${renderCards(dishes)}</div></section>`}
function renderMenu(){return pageHead('我的菜单','YOUR PERSONAL FOOD COLLECTION','收藏喜欢的味道，记住每一餐的美好。',`已收藏 <strong>${state.dishes.length}</strong> 道美味 · 留下 <strong>${state.records.length}</strong> 次回忆`)+(!query?`<section class="hero"><div class="hero-copy"><div class="hero-tag">一餐一味 · 一页一念</div><h2>人间烟火，<br>皆有<em>回甘。</em></h2><p>你的私人菜单，也是生活的另一种日记。</p><button class="hero-cta" data-action="goBook">翻开我的美食之书 ${icon('arrow')}</button></div><button type="button" class="hero-image" aria-label="美食封面"></button></section>`:'')+renderCollection(filtered(),query?'寻找记忆里的味道':'熟悉的味道，随时翻到')+foot()}
function renderFavorites(){const count=state.dishes.filter(d=>d.favorite).length;return pageHead('特别喜欢','THE FLAVORS CLOSE TO YOUR HEART','那些吃过以后，还会忍不住惦记的味道。',`收好 <strong>${count}</strong> 道心头好`)+`<section class="favorites-note"><div class="favorites-heart">${icon('heart')}</div><div><div class="eyebrow">偏爱，留给合胃口的味道</div><h2>喜欢的味道，值得再相逢。</h2><p>把念念不忘的美味收在这里，为下一餐留一点期待。</p></div><span class="favorites-seal" aria-hidden="true">偏爱<br>有味</span></section>`+renderCollection(filtered(),query?'寻找心头好的味道':'总有几道，让人惦记')+foot()}
function renderFilters(){return ['全部',...state.categories,...(state.dishes.some(d=>!d.category)?['未分类']:[])].map(c=>`<button class="chip ${c===category?'active':''}" data-action="category" data-category="${esc(c)}">${esc(c)}${c==='全部'?`<span class="num">${view==='favorites'?state.dishes.filter(d=>d.favorite).length:state.dishes.length}</span>`:''}</button>`).join('')}
function renderCards(arr){if(!arr.length){const narrow=!!query||category!=='全部',favoritePage=view==='favorites';return `<div class="empty">${icon(favoritePage?'heart':'bowl')}<h3>${narrow?'没有找到这份味道':favoritePage?'还没有特别喜欢的味道':'这里还没有美味'}</h3><p>${narrow?'试试换个关键词或分类，再找找看。':favoritePage?'在我的菜单里，点亮菜品上的小爱心，把偏爱的味道收进来。':'先记下菜名和感受，照片也可以以后再补。'}</p><button class="btn outline" data-action="${narrow?'clearFilters':favoritePage?'goMenu':'add'}">${narrow?(favoritePage?'查看全部心头好':'查看全部收藏'):favoritePage?'去我的菜单挑选':'收藏第一道菜'}</button></div>`;}return arr.map(d=>`<article class="food-card"><button class="card-photo" data-action="openDish" data-id="${d.id}" aria-label="查看${esc(d.name)}"><img src="${img(d.cover)}" alt="${esc(d.name)}" loading="lazy"><span class="photo-tag">${esc(recordOrigin(d))}</span></button><button class="heart ${d.favorite?'liked':''}" data-action="favorite" data-id="${d.id}" aria-label="${d.favorite?'取消特别喜欢':'标记特别喜欢'}：${esc(d.name)}" aria-pressed="${d.favorite}">${icon('heart')}</button><div class="card-body" data-action="openDish" data-id="${d.id}" tabindex="0" role="button" aria-label="${esc(d.name)}的品尝记录"><div class="card-line"><h3>${esc(d.name)}</h3><span class="card-category">${esc(d.category||'未分类')}</span></div><p class="card-description">${esc(d.description||'把这份美味，好好收藏。')}</p><div class="card-bottom"><span>${icon('calendar')} ${lastDate(d).replaceAll('-','.')}</span><span class="times">品尝过 ${allRecords(d.id).length} 次</span></div></div></article>`).join('')}
function refreshGrid(){if(!['menu','favorites'].includes(view))return;document.getElementById('foodGrid').innerHTML=renderCards(filtered());document.getElementById('resultCount').textContent=`共 ${filtered().length} 道`;document.getElementById('filters').innerHTML=renderFilters()}
function toggleFavorite(id){const next=structuredClone(state),d=next.dishes.find(x=>x.id===id);if(!d)return;d.favorite=!d.favorite;if(!commit(next))return;render();if(document.getElementById('detailDialog').open&&detailId===id)openDish(id);toast(d.favorite?'已加入「特别喜欢」':'已取消特别喜欢')}
function openDish(id){const d=dishBy(id);if(!d){toast('这道菜不在当前收藏中');return}detailId=id;const recs=allRecords(id),dialog=document.getElementById('detailDialog');dialog.innerHTML=`<div class="detail-hero"><div class="detail-photo-wrap"><img src="${img(d.cover)}" alt="${esc(d.name)}"></div><div class="detail-summary"><button class="icon-btn detail-close" data-action="close" aria-label="关闭菜品详情">${icon('close')}</button><div class="eyebrow">A FLAVOR TO REMEMBER</div><h2>${esc(d.name)}</h2><p class="detail-description">${esc(d.description||'每一次吃到，都值得留下一点回忆。')}</p><div class="tags"><span class="tag">${esc(d.category||'未分类')}</span>${d.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="detail-meta">${icon('camera')} ${recs.reduce((n,r)=>n+r.photos.length,0)} 张照片 <span>·</span> ${icon('clock')} 品尝过 ${recs.length} 次</div><div class="buttons"><button class="btn primary small" data-action="addAgain" data-id="${id}">${icon('plus')} 又吃到了</button><button class="btn outline small" data-action="editDish" data-id="${id}">${icon('edit')} 编辑</button><button class="icon-btn ${d.favorite?'danger':''}" data-action="favorite" data-id="${id}" aria-label="${d.favorite?'取消特别喜欢':'标记特别喜欢'}">${icon('heart')}</button></div></div></div><div class="history"><div class="history-title"><h3>关于它的美味回忆</h3><small>${recs.length} 次相遇</small></div>${recs.length?recs.map(r=>{const m=mealBy(r.mealId);return `<div class="history-item"><div class="history-date"><strong>${dateShort(r.date)}</strong>${r.date.slice(0,4)}</div><div class="history-text"><h4>${esc(m?.title||'记下一道美味')}</h4><p>${esc(r.note||'这次也很好吃。')}</p>${m?`<button class="meal-link" data-action="openMeal" data-id="${m.id}">${icon('pin')} ${esc(m.place||m.type)} · 查看这一餐</button>`:''}<div class="history-photos">${r.photos.map((p,i)=>`<button style="padding:0" data-action="photo" data-src="${esc(p)}" data-name="${esc(d.name)}" aria-label="放大第${i+1}张照片"><img src="${img(p)}" alt="${esc(d.name)}的品尝照片"></button>`).join('')}</div><button class="btn text small" data-action="editRecord" data-id="${r.id}" style="font-size:9px;padding-bottom:0">编辑这次记录</button></div></div>`}).join(''):'<p class="status-note">还没有品尝记录，点击「又吃到了」开始记录。</p>'}</div>`;if(!dialog.open)dialog.showModal()}
function openMeal(id){const m=mealBy(id);if(!m)return;const recs=state.records.filter(r=>r.mealId===id);const dialog=document.getElementById('auxDialog');dialog.style.width='610px';dialog.innerHTML=`<div class="dialog-head"><div><div class="eyebrow">A TABLE OF MEMORIES</div><h2 style="margin-top:7px">${esc(m.title||'一顿好饭')}</h2><p>${dateLong(m.date)} · ${esc(m.type)}</p></div><button class="icon-btn" data-action="close" aria-label="关闭用餐详情">${icon('close')}</button></div><div class="dialog-body"><div class="tags">${m.place?`<span class="tag">${icon('pin')} ${esc(m.place)}</span>`:''}${m.maker?`<span class="tag">制作者：${esc(m.maker)}</span>`:''}</div><p class="detail-description">${esc(m.note||'好好吃饭，就是好好生活。')}</p><div class="meal-detail-cards">${recs.map(r=>{const d=dishBy(r.dishId);return `<button class="meal-detail-card" data-action="mealDish" data-id="${d.id}"><img src="${img(r.photos[0]||d.cover)}" alt="${esc(d.name)}"><div><strong>${esc(d.name)}</strong><small>${esc(r.note||d.category)}</small></div></button>`}).join('')}</div></div><div class="dialog-actions"><button class="btn outline" data-action="editMeal" data-id="${id}">${icon('edit')} 编辑这一餐</button><button class="btn primary" data-action="close">收好这份回忆</button></div>`;if(!dialog.open)dialog.showModal()}
function bookDishes(){return state.dishes.filter(d=>bookCategory==='全部'||(bookCategory==='特别喜欢'?d.favorite:d.category===bookCategory))}
function renderBook(){const list=bookDishes();state.bookIndex=Math.max(0,Math.min(state.bookIndex||0,list.length-1));const d=list[state.bookIndex];return pageHead('翻阅菜单','THE BOOK OF YOUR FAVORITE FLAVORS','把吃过的美好，一页一页，慢慢翻。','一本属于你的美食之书')+`<div class="book-toolbar"><div style="display:flex;gap:8px"><button class="btn outline small" data-action="bookCatalog">${icon('list')} 菜单目录</button><button class="btn outline small" data-action="bookCover">${bookCover?'打开书页':'查看封面'}</button></div><select id="bookCategory" aria-label="翻阅范围">${['全部','特别喜欢',...state.categories].map(c=>`<option ${c===bookCategory?'selected':''}>${esc(c)}</option>`).join('')}</select></div><section class="book-stage">${!list.length?`<div class="empty"><h3>这一章，还在等待美味</h3><p>先收藏几道喜欢的菜，再回来翻阅。</p><button class="btn outline" data-action="add">收藏一道菜</button></div>`:bookCover?`<button class="book-cover" data-action="openBook"><div class="cover-border">${logoHtml()}<p>A TASTE OF YOUR LIFE<br>私人美食收藏</p><div class="cover-bottom">一餐一味 · 一页一念</div></div></button>`:`<div class="book" id="bookSpread"><div class="book-left"><img class="book-photo" src="${img(d.cover)}" alt="${esc(d.name)}"><span class="book-image-label">${esc(d.tags[0]||'人间烟火')} · ${esc(d.category||'美味收藏')}</span></div><div class="book-right"><div class="book-section">${esc(d.category||'美味收藏')} / MY PRIVATE MENU</div><div class="book-num">${String(state.bookIndex+1).padStart(2,'0')}</div><h2>${esc(d.name)}</h2><p class="book-intro">${esc(d.description||'把喜欢的味道，留在这一页。')}</p><div class="book-rule"></div><div class="book-info"><span>最近相遇 &nbsp; ${lastDate(d).replaceAll('-',' . ')}</span><span>已经品尝 &nbsp; ${allRecords(d.id).length} 次</span><span>${d.tags.map(t=>'# '+esc(t)).join(' &nbsp; ')}</span></div><button class="btn outline small" data-action="openDish" data-id="${d.id}">翻看这道菜的回忆 ${icon('arrow')}</button><div class="book-page"><span>笑食天下 · ${d.favorite?'心头好味道':'美味收藏'}</span><span>— ${String(state.bookIndex*2+2).padStart(2,'0')} —</span></div></div></div>`}</section><div class="book-nav"><button class="btn outline" data-action="prevBook" ${state.bookIndex===0||bookCover||!list.length?'disabled':''}>${icon('left')} 上一页</button><span class="position">${bookCover?'封面':`${list.length?state.bookIndex+1:0} / ${list.length}`}</span><button class="btn outline" data-action="nextBook" ${state.bookIndex>=list.length-1||bookCover||!list.length?'disabled':''}>下一页 ${icon('right')}</button></div><p class="book-tip">${icon('book')} 使用键盘 ← → 翻页，也可以从目录直接找到喜欢的菜。</p>`+foot()}
function flipBook(delta){const list=bookDishes();if(bookBusy||bookCover||state.bookIndex+delta<0||state.bookIndex+delta>=list.length)return;bookBusy=true;const el=document.getElementById('bookSpread');el?.classList.add('turning');setTimeout(()=>{state.bookIndex+=delta;save();render();document.getElementById('bookSpread')?.classList.add('entering');setTimeout(()=>{document.getElementById('bookSpread')?.classList.remove('entering');bookBusy=false},250)},250)}
function catalog(){const dialog=document.getElementById('auxDialog');dialog.style.width='510px';dialog.innerHTML=`<div class="dialog-head"><div><h2>菜单目录</h2><p>每一页，都有你喜欢的味道。</p></div><button class="icon-btn" data-action="close" aria-label="关闭目录">${icon('close')}</button></div><div class="dialog-body">${bookDishes().map((d,i)=>`<button data-action="jumpBook" data-index="${i}" style="display:flex;width:100%;padding:14px 0;align-items:center;border-bottom:1px solid var(--line);text-align:left;gap:14px"><img src="${img(d.cover)}" alt="" style="width:48px;height:42px;object-fit:cover;border-radius:4px"><span style="font:18px var(--serif)">${esc(d.name)}</span><span style="flex:1;border-top:1px dotted #d9cbb9"></span><span style="font:13px Georgia;color:#a28b6c">${String(i*2+1).padStart(2,'0')}</span></button>`).join('')||'<p class="status-note">这一分类里还没有菜品。</p>'}</div>`;dialog.showModal()}
function renderCalendar(){const first=(new Date(year,month,1).getDay()+6)%7,days=new Date(year,month+1,0).getDate(),cells=Math.ceil((first+days)/7)*7;let grid='';for(let i=0;i<cells;i++){const n=i-first+1;const date=new Date(year,month,n);const str=`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;const recs=recordsOn(str);const dayMeals=mealsOn(str);const photo=dayMeals.flatMap(m=>m.photos||[]).find(Boolean)||recs.map(r=>r.photos[0]||dishBy(r.dishId)?.cover).find(Boolean)||null;grid+=`<button class="day ${n<1||n>days?'outside':''} ${str===selectedDate?'selected':''} ${str===TODAY?'today':''}" data-action="selectDay" data-date="${str}" aria-label="${dateLong(str)}，${dayMeals.length}餐记录，${recs.length}道菜${dayMeals.some(m=>m.photos?.length)?'，有整桌照片':''}" aria-pressed="${str===selectedDate}"><span class="day-num">${date.getDate()}</span>${photo?`<img src="${img(photo)}" alt=""><span class="day-count">${recs.length?recs.length+' 道':'整桌照片'}</span>`:recs.length?`<span class="no-photo-mark">${icon('bowl')}<span>${recs.length} 道</span></span>`:''}</button>`}return pageHead('饮食日历','LITTLE MOMENTS, LOVELY MEALS','日子会过去，喜欢的味道会留下来。','有记录的每一天，都值得回味')+`<div class="calendar-layout"><section class="calendar-box"><div class="calendar-head"><h2>${year} 年 ${month+1} 月</h2><div class="calendar-controls"><button class="today-btn" data-action="calendarToday">今天</button><button class="icon-btn" data-action="prevMonth" aria-label="上个月">${icon('left')}</button><button class="icon-btn" data-action="nextMonth" aria-label="下个月">${icon('right')}</button></div></div><div class="week-grid">${['一','二','三','四','五','六','日'].map(d=>`<span class="week-label">周${d}</span>`).join('')}${grid}</div><div class="calendar-legend"><span class="dot"></span>图示标记有美食记录的日子 · 空白的日子也可以随时补记</div></section><aside class="day-panel">${renderDayPanel()}</aside></div>`+foot()}
function renderDayPanel(){const recs=state.records.filter(r=>r.date===selectedDate),ms=state.meals.filter(m=>m.date===selectedDate),loose=recs.filter(r=>!r.mealId);return `<header><div class="date-en">${selectedDate.replaceAll('-',' / ')}</div><h2>${+selectedDate.slice(5,7)} 月 ${+selectedDate.slice(8)} 日的味道</h2><p class="day-caption">${recs.length?`${ms.length} 餐记录 · ${recs.length} 道美味`:'平凡的一天，也值得认真吃饭。'}</p></header>${ms.map(m=>{const rs=recs.filter(r=>r.mealId===m.id);return `<article class="day-meal"><div class="day-meal-top"><span>${esc(m.type)}</span><span>${rs.length} 道菜</span></div><h3 class="day-meal-title">${esc(m.title||'一顿好饭')}</h3><p>${esc(m.place||m.maker||'把美味留在这一天。')}</p>${m.photos?.length?`<div class="day-table-photo"><img src="${img(m.photos[0])}" alt="${esc(m.title||'这一餐')}的整桌照片"><span>整桌照片 · ${m.photos.length} 张</span></div>`:''}<div class="meal-thumbs">${rs.slice(0,3).map(r=>`<img src="${img(r.photos[0]||dishBy(r.dishId).cover)}" alt="${esc(dishBy(r.dishId).name)}">`).join('')}</div><button class="btn text" data-action="openMeal" data-id="${m.id}">看看这一餐 ${icon('arrow')}</button></article>`}).join('')}${loose.map(r=>{const d=dishBy(r.dishId);return `<article class="day-meal"><div class="day-meal-top"><span>单道菜收藏</span>${icon('camera')}</div><h3 class="day-meal-title">${esc(d.name)}</h3><p>${esc(r.note||d.description)}</p><div class="meal-thumbs"><img src="${img(r.photos[0]||d.cover)}" alt="${esc(d.name)}"></div><button class="btn text" data-action="openDish" data-id="${d.id}">查看美味回忆 ${icon('arrow')}</button></article>`}).join('')}${!recs.length&&!ms.length?'<div class="calendar-empty">这一天的菜单，<br>等你来写。</div>':''}<button class="btn outline" data-action="addDate">${icon('plus')} 为这一天记一餐</button>`}
function changeMonth(delta){month+=delta;if(month<0){month=11;year--}if(month>11){month=0;year++}render()}
function renderSettings(){const size=(new Blob([JSON.stringify(state)]).size/1024).toFixed(1);return pageHead('设置与备份','KEEP YOUR MEMORIES SAFE','好好收藏，也好好保存。','<span class="prototype-tag">页面原型 v0.1</span>')+`<div class="notice">这是「笑食天下」的交互原型。新增和编辑会保存在当前浏览器中，支持导出与导入原型备份；正式版的电脑资料库、自动备份与安装程序将在后续开发。</div><div class="settings-grid"><div><section class="setting-card"><h2>收藏与备份</h2><p>把照片和文字一起收好，换一个地方也能继续回味。</p><div class="setting-row"><div><h3>导出完整备份</h3><p>${state.lastBackup?'最近导出：'+esc(state.lastBackup):'还没有导出过备份'}</p></div><button class="btn outline small" data-action="export">${icon('download')} 导出备份</button></div><div class="setting-row"><div><h3>从备份恢复</h3><p>恢复前可以先导出当前收藏，避免覆盖。</p></div><button class="btn outline small" data-action="import">${icon('upload')} 导入备份</button></div><div class="setting-row"><div><h3>自动备份</h3><p>正式版计划：有变更时每天最多一份，保留最近 7 份。</p></div><span class="setting-badge">正式版功能</span></div></section><section class="setting-card"><h2>分类与标签</h2><p>按自己的习惯整理，每道菜都能找到合适的位置。</p><div class="setting-cats">${state.categories.map(c=>`<button data-action="categoryFromSettings" data-category="${esc(c)}">${esc(c)}<span>${state.dishes.filter(d=>d.category===c).length}</span></button>`).join('')}</div><div style="margin-top:18px;display:flex;gap:13px"><button class="btn text small" data-action="manageCats">管理分类 ${icon('arrow')}</button><button class="btn text small" data-action="manageTags">管理标签 ${icon('arrow')}</button></div></section></div><div><section class="setting-card"><h2>这份私人菜单</h2><p>不用注册账号，慢慢收集属于自己的好味道。</p><div class="setting-row"><div><h3>菜品收藏</h3><p>你的菜单里，已经有了 ${state.dishes.length} 道美味。</p></div>${icon('book')}</div><div class="setting-row"><div><h3>品尝回忆</h3><p>${state.records.length} 次记录，${state.meals.length} 顿好饭。</p></div>${icon('calendar')}</div><div class="setting-row"><div><h3>原型保存方式</h3><p>当前浏览器本地存储，约 ${size} KB。<br>浏览器清理数据前，请先导出备份。</p></div>${icon('folder')}</div></section><section class="setting-card" style="background:#ece5d8"><div class="eyebrow">A TASTE OF YOUR LIFE</div>${logoHtml('about-logo')}<p>收藏喜欢的味道，<br>记住每一餐的美好。</p><p style="font-size:9px;margin-top:19px">示例照片：Unsplash · 仅用于展示界面<br>本原型无需联网即可查看已内置的照片。</p><p class="logo-source-note" style="margin-top:9px">Logo 使用你提供的原图。</p></section></div></div>`+foot()}
function showRandom(){const arr=filtered();if(!arr.length){toast('当前筛选里还没有菜，先换个分类试试。');return}const choices=arr.length>1?arr.filter(d=>d.id!==randomLast):arr;const d=choices[Math.floor(Math.random()*choices.length)];randomLast=d.id;const dialog=document.getElementById('randomDialog');dialog.innerHTML=`<button class="icon-btn random-close" data-action="close" aria-label="关闭推荐">${icon('close')}</button><img class="random-photo" src="${img(d.cover)}" alt="${esc(d.name)}"><div class="random-copy"><div class="eyebrow">HOW ABOUT THIS ONE?</div><h2>今天，吃这个怎么样？</h2><p style="font:24px var(--serif);color:var(--red);margin:13px 0">${esc(d.name)}</p><p>${esc(d.description)}</p><div class="tags"><span class="tag">${esc(d.category||'未分类')}</span>${d.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p style="font-size:9px;margin-top:17px">从${view==='favorites'?'特别喜欢':category==='全部'?'全部收藏':esc(category)}${query?'的搜索结果':''}中，为你挑选</p></div><div class="random-actions"><button class="btn outline" data-action="random">${icon('shuffle')} 换一道</button><button class="btn primary" data-action="randomDetail" data-id="${d.id}">看看这道菜 ${icon('arrow')}</button></div>`;if(!dialog.open)dialog.showModal()}
function closeDialog(button){const dialog=button.closest('dialog');if(dialog)dialog.close()}
function openForm(mode='dish',opts={}){formMode=mode;formDraft={photos:[],mealPhotos:[],date:opts.date||TODAY,dishId:opts.dishId||null,recordId:opts.recordId||null,editId:opts.editId||null,mealId:opts.mealId||null,newMealDishes:[],...opts};if(formDraft.recordId)formDraft.photos=[...(state.records.find(r=>r.id===formDraft.recordId)?.photos||[])];if(formDraft.mealId)formDraft.mealPhotos=[...(mealBy(formDraft.mealId)?.photos||[])];renderForm();const dialog=document.getElementById('formDialog');if(!dialog.open)dialog.showModal()}
function photoUploadHtml(id,photos=[],small=false,coverOnly=false){return `<label class="upload" id="drop-${id}" data-upload-zone="${id}" tabindex="0" role="button" aria-label="${coverOnly?'选择菜品封面（选填）':'选择美食照片（选填）'}">${icon('upload')}<strong>${coverOnly?'添加或更换封面（选填）':small?'添加照片（选填）':'添加美食照片（选填）'}</strong><p>${coverOnly?'选择一张照片作为菜品封面，不改变原有品尝记录。':'可以先填写其他信息，保存后随时编辑补图。'}<br>点击选择或拖入 · JPG / PNG / WebP${coverOnly?'':' · 支持多张'}</p><input id="${id}" type="file" accept="image/jpeg,image/png,image/webp" ${coverOnly?'':'multiple'} hidden data-photo-input="${id}"><span class="upload-preview" id="preview-${id}">${photos.map((p,i)=>`<span style="position:relative;display:inline-block"><img src="${img(p)}" alt="已选美食照片 ${i+1}"><button type="button" data-action="removeUpload" data-input="${esc(id)}" data-index="${i}" style="position:absolute;right:2px;top:2px;background:#fffdf4dd;border-radius:50%;height:20px;width:20px;padding:0" aria-label="移除照片${i+1}">×</button></span>`).join('')}</span></label>`}
function renderForm(){const dialog=document.getElementById('formDialog'),editDish=dishBy(formDraft.editId),record=state.records.find(r=>r.id===formDraft.recordId),existing=dishBy(formDraft.dishId||record?.dishId),meal=mealBy(formDraft.mealId),edit=!!(editDish||record||meal);const title=editDish?'编辑菜品收藏':record?'编辑这次品尝':meal?'编辑这一餐':'记下一道美味';dialog.innerHTML=`<div class="dialog-head"><div><h2>${title}</h2><p>${editDish?'把这道菜，整理成你喜欢的样子。':'先记下好味道，照片可以以后慢慢补。'}</p></div><button class="icon-btn" data-action="close" aria-label="关闭录入">${icon('close')}</button></div><form id="recordForm"><div class="dialog-body">${!edit&&!existing?`<div class="form-tabs"><button type="button" class="${formMode==='dish'?'active':''}" data-action="formDish">收藏一道菜</button><button type="button" class="${formMode==='meal'?'active':''}" data-action="formMeal">记录一顿饭</button></div>`:''}${formMode==='meal'?renderMealFields(meal):renderDishFields(editDish,existing,record)}<div id="formError" class="error" role="alert"></div></div><div class="dialog-actions"><small>${editDish?'菜品资料会在菜单和书本中同步更新。':'原型记录保存在当前浏览器，可在设置中导出。'}</small><button type="button" class="btn outline" data-action="close">取消</button><button type="submit" class="btn primary">${icon('check')} ${edit?'保存修改':'收好这份美味'}</button></div></form>`;bindUploadZones();dialog.querySelector('form').addEventListener('submit',submitForm)}
function renderDishFields(editDish,existing,record){const d=editDish||existing;return (editDish?photoUploadHtml('dishPhotos',formDraft.photos,false,true)+`<div class="field"><label>${d.cover?'当前封面与已有照片':'已有照片，可选作封面'}</label><div class="inline-picks">${[...new Set(allRecords(d.id).flatMap(r=>r.photos).concat(d.cover))].filter(Boolean).map((p,i)=>`<button type="button" data-action="coverPick" data-photo="${esc(p)}" class="${(formDraft.cover||d.cover)===p?'selected':''}" aria-label="选择第${i+1}张作为封面"><img src="${img(p)}" alt="封面候选${i+1}" style="height:57px;width:76px;object-fit:cover;border-radius:3px"></button>`).join('')}</div></div>`:photoUploadHtml('dishPhotos',formDraft.photos))+`<div class="field"><label for="dishName">菜名<i>*</i></label><input id="dishName" name="name" required maxlength="60" value="${esc(d?.name||formDraft.name||'')}" ${existing?'readonly':''} placeholder="这道让你念念不忘的菜，叫什么？" autocomplete="off"><div id="duplicateHint" style="margin-top:8px;font-size:10px;color:#a27558"></div></div>${!existing?`<div class="form-row"><div class="field"><label for="dishCategory">主要分类</label><select id="dishCategory" name="category"><option value="">未分类</option>${state.categories.map(c=>`<option ${c===(d?.category||formDraft.category)?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="field"><label for="dishTags">标签</label><input id="dishTags" name="tags" placeholder="家常，清淡，下饭…" value="${esc(d?.tags.join('，')||formDraft.tags||'')}" maxlength="150"></div></div><div class="field"><label for="dishDescription">这道菜的个人描述</label><textarea id="dishDescription" name="description" placeholder="什么地方，让你喜欢上了它？" maxlength="1000">${esc(d?.description||formDraft.description||'')}</textarea></div>`:`<div class="form-hint">为「${esc(d.name)}」追加一次品尝记录，菜品收藏会保留在原来的位置。</div>`}${!editDish?`<div class="form-row"><div class="field"><label for="recordDate">品尝日期<i>*</i></label><input type="date" id="recordDate" name="date" value="${record?.date||formDraft.date}" required></div><div class="field"><label for="recordMeal">归入一顿饭</label><select name="mealId" id="recordMeal"><option value="">先单独收藏</option>${state.meals.filter(m=>m.date===(record?.date||formDraft.date)).map(m=>`<option value="${m.id}" ${m.id===record?.mealId?'selected':''}>${esc(m.title||m.type)}</option>`).join('')}</select></div></div><div class="field"><label for="recordNote">这一次的感受</label><textarea id="recordNote" name="note" placeholder="今天在哪里吃到？口味怎么样？想记住什么？" maxlength="2000">${esc(record?.note||formDraft.note||'')}</textarea></div>`:''}`}
function renderMealFields(meal){const selected=meal?state.records.filter(r=>r.mealId===meal.id).map(r=>r.dishId):[];return `<div class="form-row"><div class="field"><label for="mealDate">用餐日期<i>*</i></label><input id="mealDate" name="date" type="date" required value="${meal?.date||formDraft.date}"></div><div class="field"><label for="mealType">餐次</label><select id="mealType" name="type">${['早餐','午餐','晚餐','加餐','其他'].map(t=>`<option ${(meal?.type||'晚餐')===t?'selected':''}>${t}</option>`).join('')}</select></div></div><div class="field"><label for="mealTitle">给这一餐起个名字</label><input id="mealTitle" name="title" maxlength="80" placeholder="比如：周末在家，好好吃饭" value="${esc(meal?.title||'')}"></div><div class="form-row"><div class="field"><label for="mealPlace">地点 / 店名</label><input id="mealPlace" name="place" maxlength="100" placeholder="家里，或一家宝藏小店" value="${esc(meal?.place||'')}"></div><div class="field"><label for="mealMaker">谁做的</label><input id="mealMaker" name="maker" maxlength="60" placeholder="自己、家人、店里的师傅…" value="${esc(meal?.maker||'')}"></div></div><section class="meal-photo-block"><div class="meal-photo-heading"><h3>整桌照片</h3><span>选填 · 最多 12 张</span></div><p class="meal-photo-help">把满桌好菜和相聚的气氛一起收好，也可以先只记整桌照片，之后再补菜品。</p>${photoUploadHtml('mealPhotos',formDraft.mealPhotos||[])}</section><div class="field"><label>这一餐吃了什么</label><p class="meal-dishes-hint">可选已有菜品或添加新菜；有整桌照片时，也可以稍后再补。</p><div class="meal-picks">${state.dishes.map(d=>`<label class="pick"><input type="checkbox" name="dishIds" value="${d.id}" ${selected.includes(d.id)?'checked':''}><img src="${img(d.cover)}" alt=""><span>${esc(d.name)}</span></label>`).join('')}</div><div id="newMealDishes"></div><button class="btn outline small" type="button" data-action="newMealDish">${icon('plus')} 这餐有新菜，添加一份</button></div><div class="field"><label for="mealNote">整餐备注</label><textarea id="mealNote" name="note" maxlength="2000" placeholder="和谁一起吃的？有什么想留下的回忆？">${esc(meal?.note||'')}</textarea></div>`}
async function filesToPhotos(files){
 const list=[...files];if(list.length>12)throw Error('一次最多选择 12 张照片。');
 const photos=[];
 for(const file of list){
  if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请选择 JPG、PNG 或 WebP 照片。');
  if(file.size>25*1024*1024)throw Error('单张照片请小于 25 MB。');
  const url=URL.createObjectURL(file),image=new Image(),canvas=document.createElement('canvas');
  try{
   await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('有一张照片无法读取，请换一张试试。'));image.src=url;});
   const scale=Math.min(1,1000/Math.max(image.naturalWidth,image.naturalHeight));
   canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));
   canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);
   const photo=canvas.toDataURL('image/jpeg',.8);if(photo==='data:,')throw Error('照片无法处理，请换一张试试。');photos.push(photo);
  }finally{image.onload=image.onerror=null;image.removeAttribute('src');canvas.width=canvas.height=1;URL.revokeObjectURL(url);}
 }
 return photos;
}
function bindUploadZones(){document.querySelectorAll('[data-upload-zone]').forEach(zone=>{if(zone.dataset.bound)return;zone.dataset.bound='1';zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragover')});zone.addEventListener('dragleave',()=>zone.classList.remove('dragover'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragover');processPhotos(zone.dataset.uploadZone,e.dataTransfer.files)});zone.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();document.getElementById(zone.dataset.uploadZone).click()}})});document.querySelectorAll('[data-photo-input]').forEach(input=>{if(input.dataset.bound)return;input.dataset.bound='1';input.addEventListener('change',()=>processPhotos(input.id,input.files))});document.getElementById('dishName')?.addEventListener('input',e=>{const match=state.dishes.find(d=>d.name.trim()===e.target.value.trim()&&d.id!==formDraft.editId);document.getElementById('duplicateHint').innerHTML=match&&!formDraft.dishId?`已有同名收藏。保存时请决定追加记录，或独立收藏。<label style="margin-top:8px"><input type="radio" name="duplicateChoice" value="${match.id}" style="width:auto;display:inline;min-height:0"> 添加到已有菜品</label><label style="margin-top:6px"><input type="radio" name="duplicateChoice" value="new" style="width:auto;display:inline;min-height:0"> 作为新的同名菜收藏</label>`:''});document.getElementById('recordDate')?.addEventListener('change',e=>{const select=document.getElementById('recordMeal');select.innerHTML='<option value="">先单独收藏</option>'+state.meals.filter(m=>m.date===e.target.value).map(m=>`<option value="${m.id}">${esc(m.title||m.type)}</option>`).join('')})}
async function processPhotos(inputId,files){if(!files.length)return;try{if(inputId==='dishPhotos'&&formDraft.editId&&files.length>1)throw Error('封面请选择一张照片；更多照片可以添加到品尝记录。');const photos=await filesToPhotos(files);if(inputId==='dishPhotos'){if(formDraft.editId){formDraft.photos=[];formDraft.cover=null;document.querySelectorAll('[data-action=coverPick]').forEach(el=>el.classList.remove('selected'))}if(formDraft.photos.length+photos.length>12)throw new Error('每条品尝记录最多 12 张照片。');formDraft.photos.push(...photos)}else{const nd=formDraft.newMealDishes.find(d=>d.id===inputId);if(nd)nd.photos.push(...photos)}const all=inputId==='dishPhotos'?formDraft.photos:formDraft.newMealDishes.find(d=>d.id===inputId)?.photos||[];document.getElementById('preview-'+inputId).innerHTML=all.map((p,i)=>`<span style="position:relative;display:inline-block"><img src="${img(p)}" alt="已选照片 ${i+1}"><button type="button" data-action="removeUpload" data-input="${inputId}" data-index="${i}" style="position:absolute;right:2px;top:2px;background:#fffdf4dd;border-radius:50%;height:20px;width:20px;padding:0;font-size:14px" aria-label="移除照片${i+1}">×</button></span>`).join('');document.getElementById('formError').textContent=''}catch(e){document.getElementById('formError').textContent=e.message}}
function addMealDish(){const id=uid();formDraft.newMealDishes.push({id,photos:[]});const item=document.createElement('div');item.className='new-meal-item';item.id='new-'+id;item.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px"><span style="font-size:11px;color:#8b7559">新菜品</span><button type="button" class="icon-btn" data-action="removeMealDish" data-id="${id}" aria-label="移除新菜品">${icon('close')}</button></div><div class="form-row"><div class="field"><input name="newName-${id}" required placeholder="菜名" aria-label="新菜名称" maxlength="60"></div><div class="field"><select name="newCategory-${id}" aria-label="新菜分类"><option value="">未分类</option>${state.categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></div></div>${photoUploadHtml(id,[],true)}`;document.getElementById('newMealDishes').append(item);bindUploadZones()}
function submitForm(e){e.preventDefault();const data=new FormData(e.target),error=document.getElementById('formError');const next=structuredClone(state);try{if(formDraft.editId){const d=next.dishes.find(d=>d.id===formDraft.editId);d.name=String(data.get('name')).trim();if(!d.name)throw Error('请填写菜名。');d.category=data.get('category');d.tags=String(data.get('tags')).split(/[,，、]/).map(s=>s.trim()).filter(Boolean);d.description=String(data.get('description')).trim();d.cover=formDraft.photos[0]||formDraft.cover||d.cover||''}
 else if(formMode==='meal'){const selected=data.getAll('dishIds'),newItems=formDraft.newMealDishes;if(!selected.length&&!newItems.length&&!formDraft.mealPhotos.length&&!formDraft.mealId)throw Error('请添加整桌照片，或选择、添加至少一道菜。');for(const n of newItems){if(!String(data.get('newName-'+n.id)||'').trim())throw Error('请给每一道新菜填写菜名。');}const date=data.get('date');if(!globalThis.FoodCalendarData.dateOk(date))throw Error('请选择有效的用餐日期。');let m=next.meals.find(m=>m.id===formDraft.mealId);if(!m){m={id:uid()};next.meals.push(m)}Object.assign(m,{date,type:data.get('type'),title:String(data.get('title')).trim()||data.get('type'),place:String(data.get('place')).trim(),maker:String(data.get('maker')).trim(),note:String(data.get('note')).trim(),photos:[...formDraft.mealPhotos]});next.records.filter(r=>r.mealId===m.id&&!selected.includes(r.dishId)).forEach(r=>r.mealId=null);for(const id of selected){const old=next.records.find(r=>r.mealId===m.id&&r.dishId===id);if(old)old.date=date;else{const d=next.dishes.find(d=>d.id===id);next.records.push({id:uid(),dishId:id,mealId:m.id,date,note:'',photos:d.cover?[d.cover]:[]})}}for(const n of newItems){const id=uid();next.dishes.push({id,name:String(data.get('newName-'+n.id)).trim(),category:data.get('newCategory-'+n.id),tags:[],favorite:false,description:'',cover:n.photos[0]||'',created:date});next.records.push({id:uid(),dishId:id,mealId:m.id,date,note:'',photos:n.photos})}}
 else {let id=formDraft.dishId;const oldRecord=next.records.find(r=>r.id===formDraft.recordId);if(oldRecord)id=oldRecord.dishId;const name=String(data.get('name')).trim();if(!name)throw Error('请填写菜名。');if(!id){const match=next.dishes.find(d=>d.name===name);if(match&&!data.get('duplicateChoice'))throw Error('有一道同名收藏，请在菜名下方选择追加记录或独立收藏。');if(match&&data.get('duplicateChoice')!=='new')id=match.id;else{id=uid();next.dishes.push({id,name,category:data.get('category')||'',tags:String(data.get('tags')||'').split(/[,，、]/).map(t=>t.trim()).filter(Boolean),favorite:false,description:String(data.get('description')||'').trim(),cover:formDraft.photos[0]||'',created:data.get('date')})}}const mealId=data.get('mealId')||null;const linked=next.meals.find(m=>m.id===mealId);const date=linked?.date||data.get('date');if(!globalThis.FoodCalendarData.dateOk(date))throw Error('请选择有效的品尝日期。');if(oldRecord)Object.assign(oldRecord,{date,mealId,note:String(data.get('note')).trim(),photos:formDraft.photos});else next.records.push({id:uid(),dishId:id,date,mealId,note:String(data.get('note')).trim(),photos:formDraft.photos});const savedDish=next.dishes.find(d=>d.id===id);if(savedDish&&!savedDish.cover&&formDraft.photos[0])savedDish.cover=formDraft.photos[0];}
 if(!commit(next))return;document.getElementById('formDialog').close();render();if(detailId&&document.getElementById('detailDialog').open)openDish(detailId);if(formDraft.mealId&&document.getElementById('auxDialog').open)openMeal(formDraft.mealId);toast(formDraft.editId||formDraft.recordId||formDraft.mealId?'已保存修改，回忆也一起更新了。':'这份美味，已经好好收下。')
 }catch(err){error.textContent=err.message;error.scrollIntoView({block:'nearest'})}}
function exportBackup(){const next=structuredClone(state);next.lastBackup=new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});if(!commit(next))return;const backup=structuredClone(state);backup.dishes.forEach(d=>d.cover=d.cover?img(d.cover):'');backup.records.forEach(r=>r.photos=r.photos.map(img));backup.meals.forEach(m=>{if(m.photos)m.photos=m.photos.map(img)});const blob=new Blob([JSON.stringify({app:'笑食天下',format:'prototype-1',data:backup})],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='笑食天下-原型备份-'+TODAY+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000);render();toast('备份文件已生成，请保存在可靠的位置。')}
function validBackup(obj){if(obj?.app!=='笑食天下'||obj?.format!=='prototype-1')return false;const s=obj.data;if(s?.version!==1||!Array.isArray(s.dishes)||!Array.isArray(s.records)||!Array.isArray(s.meals)||!Array.isArray(s.categories)||s.dishes.length>5000||s.records.length>30000)return false;const safeDate=value=>globalThis.FoodCalendarData.dateOk(value);const safeId=id=>typeof id==='string'&&/^[a-zA-Z0-9-]{1,80}$/.test(id);const safePhoto=p=>typeof p==='string'&&(Object.hasOwn(ASSETS,p)||/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(p));if(s.tagOrder!==undefined&&(!Array.isArray(s.tagOrder)||!s.tagOrder.every(t=>typeof t==='string'&&t.trim()&&t.length<=150)||new Set(s.tagOrder).size!==s.tagOrder.length))return false;if(!s.categories.every(c=>typeof c==='string'&&c.length<61)||new Set(s.categories).size!==s.categories.length)return false;const ids=new Set(s.dishes.map(d=>d.id)),meals=new Set(s.meals.map(m=>m.id));if(ids.size!==s.dishes.length||meals.size!==s.meals.length)return false;if(!s.dishes.every(d=>safeId(d.id)&&typeof d.name==='string'&&d.name.trim()&&d.name.length<=60&&typeof d.description==='string'&&typeof d.category==='string'&&Array.isArray(d.tags)&&d.tags.every(t=>typeof t==='string')&&(d.cover===''||safePhoto(d.cover))&&safeDate(d.created)))return false;if(!s.meals.every(m=>safeId(m.id)&&safeDate(m.date)&&['title','type','place','maker','note'].every(k=>typeof m[k]==='string')&&(m.photos===undefined||(Array.isArray(m.photos)&&m.photos.length<=100&&m.photos.every(safePhoto)))))return false;return s.records.every(r=>safeId(r.id)&&ids.has(r.dishId)&&(!r.mealId||meals.has(r.mealId))&&safeDate(r.date)&&typeof r.note==='string'&&Array.isArray(r.photos)&&r.photos.length<=100&&r.photos.every(safePhoto))}
function importBackup(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{const f=input.files[0];if(!f)return;try{if(f.size>30*1024*1024)throw Error('备份文件过大，当前原型支持 30 MB 以内的备份。');const obj=JSON.parse(await f.text());if(!validBackup(obj))throw Error('文件不是有效的「笑食天下」原型备份。');const dialog=document.getElementById('auxDialog');dialog.style.width='440px';dialog.innerHTML=`<div class="dialog-head"><h2>恢复这份收藏？</h2><button class="icon-btn" data-action="close" aria-label="取消恢复">${icon('close')}</button></div><div class="dialog-body"><p class="status-note">备份包含 ${obj.data.dishes.length} 道菜、${obj.data.records.length} 次品尝记录。恢复会替换当前浏览器内的资料。</p><div class="notice" style="margin:17px 0 0">建议先导出当前收藏，再恢复备份。</div></div><div class="dialog-actions"><button class="btn outline" id="exportBeforeRestore">先导出当前资料</button><button class="btn primary" id="confirmRestore">确认恢复</button></div>`;dialog.showModal();document.getElementById('exportBeforeRestore').onclick=exportBackup;document.getElementById('confirmRestore').onclick=()=>{const next=structuredClone(obj.data);const bundled=new Map(Object.entries(ASSETS).map(([key,value])=>[value,key]));next.dishes.forEach(d=>d.cover=bundled.get(d.cover)||d.cover);next.records.forEach(r=>r.photos=r.photos.map(p=>bundled.get(p)||p));next.bookIndex=0;if(commit(next)){dialog.close();category='全部';favOnly=false;query='';render();toast('收藏已恢复，照片与记录都回来了。')}}}catch(e){toast(e.message)}};input.click()}
function manageCategories(){const dialog=document.getElementById('auxDialog');dialog.style.width='490px';dialog.innerHTML=`<div class="dialog-head"><div><h2>管理分类</h2><p>改名会同步更新菜品，移除后菜品归入未分类。</p></div><button class="icon-btn" data-action="close" aria-label="关闭分类管理">${icon('close')}</button></div><form id="categoryForm"><div class="dialog-body" id="categoryRows">${state.categories.map((c,i)=>`<div class="manage-item"><input name="cat-${i}" value="${esc(c)}" maxlength="30" aria-label="分类名称"><small>${state.dishes.filter(d=>d.category===c).length} 道</small><button type="button" class="icon-btn" data-action="removeCatRow" aria-label="移除分类${esc(c)}">${icon('close')}</button><input type="hidden" name="old-${i}" value="${esc(c)}"></div>`).join('')}<button type="button" class="btn text small" data-action="newCatRow">${icon('plus')} 新增分类</button><div id="catError" class="error"></div></div><div class="dialog-actions"><button type="button" class="btn outline" data-action="close">取消</button><button class="btn primary" type="submit">保存分类</button></div></form>`;dialog.showModal();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const rows=[...document.querySelectorAll('#categoryRows .manage-item')];const pairs=rows.map(row=>({old:row.querySelector('input[type=hidden]').value,name:row.querySelector('input:not([type=hidden])').value.trim()}));const names=pairs.map(p=>p.name);if(names.some(n=>!n)||new Set(names).size!==names.length||names.includes('全部')||names.includes('未分类')||names.includes('特别喜欢')){document.getElementById('catError').textContent='分类名称不能为空、重复，或使用「全部」「未分类」「特别喜欢」。';return}const next=structuredClone(state);next.categories=names;next.dishes.forEach(d=>{d.category=pairs.find(p=>p.old===d.category)?.name||''});if(commit(next)){category='全部';bookCategory='全部';dialog.close();render();toast('分类整理好了。')}}}
function orderedTags(){const used=[...new Set(state.dishes.flatMap(d=>d.tags))];return [...new Set([...(state.tagOrder||[]).filter(t=>used.includes(t)),...used])]}
function manageTags(){const tags=orderedTags();const dialog=document.getElementById('auxDialog');dialog.style.width='490px';dialog.innerHTML=`<div class="dialog-head"><div><h2>管理标签</h2><p>修改后，会同步更新所有使用它的菜品。</p></div><button class="icon-btn" data-action="close" aria-label="关闭标签管理">${icon('close')}</button></div><form id="tagsForm"><div class="dialog-body" id="tagRows">${tags.map((t,i)=>`<div class="manage-item"><input name="tag-${i}" value="${esc(t)}" maxlength="30" data-old="${esc(t)}" aria-label="标签名称"><small>${state.dishes.filter(d=>d.tags.includes(t)).length} 道</small><button type="button" class="icon-btn" data-action="removeCatRow" aria-label="移除标签${esc(t)}">${icon('close')}</button></div>`).join('')||'<p class="status-note">还没有标签，可以在编辑菜品时添加。</p>'}<div id="tagsError" class="error"></div></div><div class="dialog-actions"><button type="button" class="btn outline" data-action="close">取消</button><button class="btn primary" type="submit">保存标签</button></div></form>`;dialog.showModal();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const pairs=[...dialog.querySelectorAll('[data-old]')].map(i=>({old:i.dataset.old,name:i.value.trim()}));if(pairs.some(p=>!p.name)){document.getElementById('tagsError').textContent='标签名称不能为空。';return}const next=structuredClone(state);next.tagOrder=[...new Set(pairs.map(p=>p.name))];const ranks=new Map(next.tagOrder.map((t,i)=>[t,i]));next.dishes.forEach(d=>d.tags=[...new Set(d.tags.map(t=>pairs.find(p=>p.old===t)?.name).filter(Boolean))].sort((a,b)=>ranks.get(a)-ranks.get(b)));if(commit(next)){dialog.close();render();toast('标签整理好了。')}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;const handlers={goBook:()=>setView('book'),goMenu:()=>setView('menu'),openDish:()=>openDish(id),favorite:()=>toggleFavorite(id),category:()=>{category=b.dataset.category;refreshGrid()},clearFilters:()=>{category='全部';favOnly=view==='favorites';query='';document.getElementById('globalSearch').value='';render()},add:()=>openForm(),close:()=>closeDialog(b),addAgain:()=>openForm('dish',{dishId:id}),editDish:()=>openForm('dish',{editId:id}),editRecord:()=>openForm('dish',{recordId:id}),openMeal:()=>openMeal(id),editMeal:()=>{document.getElementById('auxDialog').close();openForm('meal',{mealId:id})},mealDish:()=>{document.getElementById('auxDialog').close();openDish(id)},bookCover:()=>{bookCover=!bookCover;render()},openBook:()=>{bookCover=false;render()},prevBook:()=>flipBook(-1),nextBook:()=>flipBook(1),bookCatalog:catalog,jumpBook:()=>{state.bookIndex=Number(b.dataset.index);bookCover=false;save();document.getElementById('auxDialog').close();render()},selectDay:()=>{selectedDate=b.dataset.date;const parts=selectedDate.split('-');year=+parts[0];month=+parts[1]-1;render()},calendarToday:()=>{selectedDate=TODAY;year=2026;month=9;render()},prevMonth:()=>changeMonth(-1),nextMonth:()=>changeMonth(1),addDate:()=>openForm('meal',{date:selectedDate}),random:showRandom,randomDetail:()=>{document.getElementById('randomDialog').close();openDish(id)},formDish:()=>{formMode='dish';formDraft.photos=[];formDraft.newMealDishes=[];renderForm()},formMeal:()=>{formMode='meal';formDraft.photos=[];formDraft.newMealDishes=[];renderForm()},newMealDish:addMealDish,removeMealDish:()=>{formDraft.newMealDishes=formDraft.newMealDishes.filter(d=>d.id!==id);document.getElementById('new-'+id).remove()},coverPick:()=>{formDraft.cover=b.dataset.photo;formDraft.photos=[];const preview=document.getElementById('preview-dishPhotos');if(preview)preview.innerHTML='';document.querySelectorAll('[data-action=coverPick]').forEach(el=>el.classList.toggle('selected',el===b))},removeUpload:()=>{const arr=b.dataset.input==='dishPhotos'?formDraft.photos:b.dataset.input==='mealPhotos'?formDraft.mealPhotos:formDraft.newMealDishes.find(d=>d.id===b.dataset.input)?.photos;if(arr){arr.splice(Number(b.dataset.index),1);const preview=document.getElementById('preview-'+b.dataset.input);preview.innerHTML=arr.map((p,i)=>`<span style="position:relative"><img src="${img(p)}" alt="已选照片"><button type="button" data-action="removeUpload" data-input="${esc(b.dataset.input)}" data-index="${i}" style="position:absolute;right:2px;top:2px;background:#fffdf4dd;border-radius:50%;height:20px;width:20px;padding:0" aria-label="移除照片${i+1}">×</button></span>`).join('')}},export:exportBackup,import:importBackup,manageCats:manageCategories,manageTags:manageTags,categoryFromSettings:()=>{setView('menu');category=b.dataset.category;render()},removeCatRow:()=>b.closest('.manage-item').remove(),newCatRow:()=>{const n=document.querySelectorAll('#categoryRows .manage-item').length+'-'+Date.now();b.insertAdjacentHTML('beforebegin',`<div class="manage-item"><input name="cat-${n}" maxlength="30" placeholder="新分类名称" aria-label="新分类名称"><small>0 道</small><button type="button" class="icon-btn" data-action="removeCatRow" aria-label="移除新分类">${icon('close')}</button><input type="hidden" value="__new-${n}"></div>`)},photo:()=>{const dialog=document.getElementById('auxDialog');dialog.style.width='800px';dialog.innerHTML=`<div class="dialog-head"><h2>${esc(b.dataset.name)}</h2><button class="icon-btn" data-action="close" aria-label="关闭大图">${icon('close')}</button></div><img src="${img(b.dataset.src)}" alt="${esc(b.dataset.name)}" style="display:block;width:100%;max-height:70vh;object-fit:contain;background:#e9e1d3">`;dialog.showModal()}};handlers[a]?.()});
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));document.getElementById('addGlobal').onclick=()=>openForm();document.querySelector('.brand').onclick=e=>{e.preventDefault();setView('menu')};document.getElementById('globalSearch').addEventListener('input',e=>{const value=e.target.value;if(!['menu','favorites'].includes(view))setView('menu');query=value.trim();e.target.value=value;render()});document.addEventListener('change',e=>{if(e.target.id==='sortSelect'){sort=e.target.value;refreshGrid()}if(e.target.id==='bookCategory'){bookCategory=e.target.value;state.bookIndex=0;bookCover=false;render()}});document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select,[contenteditable]'))return;if(e.key==='/'&&!document.querySelector('dialog[open]')){e.preventDefault();document.getElementById('globalSearch').focus()}if(document.querySelector('dialog[open]'))return;if(view==='book'){if(e.key==='ArrowLeft')flipBook(-1);if(e.key==='ArrowRight')flipBook(1)}if(e.key==='Enter'&&e.target.matches('.card-body'))e.target.click()});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
render();
